# Basic OOP Program Example
class Animal:
    """Base class for animals."""
    def __init__(self, name):
        self.name = name
        print(f"{self.name} created.")

def make_sound(self):
    """Abstract method to make a sound."""
    raise NotImplementedError("Subclass must implement abstract method")

class Dog(Animal):
    """Represents a dog."""
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed

def make_sound(self):
    return f"{self.name} says Woof! (I am a {self.breed})."

class Cat(Animal):
    """Represents a cat."""
    def __init__(self, name):
        super().__init__(name)

def make_sound(self):
    return f"{self.name} says Meow! (I am graceful)."

# Client code
if __name__ == "__main__":
    print("--- Testing OOP Concepts ---")
    doggo = Dog("Buddy", "Golden Retriever")
    catty = Cat("Whiskers")

    print(f"Dog sound: {doggo.make_sound()}")
    print(f"Cat sound: {catty.make_sound()}")

class Animal:
    """Base class demonstrating basic attributes."""
    def __init__(self, name):
        self.name = name
        print(f'{self.name} initialized.')

    def speak(self):
        raise NotImplementedError("Subclass must implement abstract method")

class Dog(Animal):
    """Derived class demonstrating inheritance and polymorphism."""
    def __init__(self, name, breed):
        # Calling the parent constructor (super()) for initialization
        super().__init__(name)
        self.breed = breed

    def speak(self):
        # Overriding the parent method (polymorphism)
        return f'{self.name} barks: Woof! I am a {self.breed}.'

class Cat(Animal):
    """Another derived class."""
    def __init__(self, name):
        super().__init__(name)

    def speak(self):
        return f'{self.name} meows: Meow! I am a graceful cat.'

# Demonstration of OOP concepts:
print("\n--- Creating Dog object ---")
dog = Dog("Buddy", "Golden Retriever")
print(dog.speak())

print("\n--- Creating Cat object ---")
cat = Cat("Whiskers")
print(cat.speak())
